## ars.R -----------------------------------------------------------------
##
## Adaptive Rejection Sampling (ARS) for univariate log-concave densities,
## following Gilks, W. R., & Wild, P. (1992). "Adaptive Rejection Sampling
## for Gibbs Sampling." JRSS Series C, 41(2), 337-348.
##
## Public API:
##   ars(g, n, lower, upper, x_init, ..., deriv_eps, tol, max_iter, verbose)
##   test(seed, n, verbose)
##
## The implementation is organised as a small pipeline of single-purpose
## helper functions (all prefixed with '.') that build and query the
## piecewise-linear "hulls" used by the algorithm:
##
##   .validate_inputs        input checking
##   .make_h                 wraps the user density as a log-density h(x)
##   .h_prime                numerical derivative of h
##   .initial_abscissae      picks/expands starting points x_1 < ... < x_k
##   .build_hull             builds upper-hull tangent lines + intersections
##   .eval_upper / .eval_lower  evaluate the envelope / squeeze functions
##   .segment_log_weight / .segment_probs / .sample_segment / .sample_from_hull
##                           piecewise-exponential sampling from the upper hull
##   .check_concavity_at_insert  detects violations of log-concavity
##   .update_hull            inserts a newly evaluated point into the hull
## -------------------------------------------------------------------------

## ---- input validation ---------------------------------------------------

.validate_inputs <- function(g, n, lower, upper, x_init) {
  if (!is.function(g)) {
    stop("ars: 'g' must be a function that computes the (possibly unnormalized) density.")
  }
  if (!is.numeric(n) || length(n) != 1 || is.na(n) || n != round(n) || n <= 0) {
    stop("ars: 'n' must be a single positive integer (number of samples requested).")
  }
  if (!is.numeric(lower) || !is.numeric(upper) || length(lower) != 1 || length(upper) != 1) {
    stop("ars: 'lower' and 'upper' must be single numeric values (Inf/-Inf allowed).")
  }
  if (!(lower < upper)) {
    stop("ars: 'lower' must be strictly less than 'upper' (invalid domain).")
  }
  if (!is.null(x_init)) {
    if (!is.numeric(x_init) || length(x_init) < 2) {
      stop("ars: 'x_init' must be a numeric vector with at least 2 starting points.")
    }
    if (any(x_init <= lower) || any(x_init >= upper)) {
      stop("ars: all values of 'x_init' must lie strictly inside (lower, upper).")
    }
  }
  invisible(TRUE)
}

## ---- log-density and its derivative -------------------------------------

## Wraps the user's density g(x, ...) as h(x) = log g(x, ...), checking that
## g returns a valid (non-negative, non-NaN) density.
.make_h <- function(g, ...) {
  function(x) {
    gx <- g(x, ...)
    if (any(is.na(gx))) {
      stop("ars: the density function returned NA/NaN; check its domain and parameters.")
    }
    if (any(gx < 0)) {
      stop("ars: the density function returned a negative value; it is not a valid density.")
    }
    log(gx)
  }
}

## Central finite-difference derivative of h, vectorized over x.
.h_prime <- function(h, x, eps = 1e-6) {
  (h(x + eps) - h(x - eps)) / (2 * eps)
}

## ---- initial abscissae ----------------------------------------------------

## Picks (or accepts user-supplied) starting points and, on unbounded sides,
## expands outward until the required slope conditions for a proper
## (integrable) envelope hold: h'(x_1) > 0 if lower == -Inf, and
## h'(x_k) < 0 if upper == Inf. Failure to find such points after
## `max_expand` doublings signals a misspecified domain or a density that
## is not log-concave.
.initial_abscissae <- function(h, hp, lower, upper, x_init = NULL, max_expand = 50) {
  if (is.null(x_init)) {
    if (is.finite(lower) && is.finite(upper)) {
      x <- c(lower + 0.25 * (upper - lower), lower + 0.75 * (upper - lower))
    } else if (is.finite(lower)) {
      x <- c(lower + 0.5, lower + 1.5)
    } else if (is.finite(upper)) {
      x <- c(upper - 1.5, upper - 0.5)
    } else {
      x <- c(-1, 1)
    }
  } else {
    x <- x_init
  }
  x <- sort(unique(x))
  if (length(x) < 2) {
    stop("ars: need at least two distinct initial abscissae strictly inside (lower, upper).")
  }

  if (!is.finite(lower)) {
    step <- 1
    tries <- 0
    while (hp(x[1]) <= 1e-8) {
      tries <- tries + 1
      if (tries > max_expand) {
        stop("ars: could not find a left starting point with positive log-density slope. ",
             "The density may not be log-concave on this domain, or 'lower'/'x_init' may be misspecified.")
      }
      x <- c(x[1] - step, x)
      step <- step * 2
    }
  }
  if (!is.finite(upper)) {
    step <- 1
    tries <- 0
    k <- length(x)
    while (hp(x[k]) >= -1e-8) {
      tries <- tries + 1
      if (tries > max_expand) {
        stop("ars: could not find a right starting point with negative log-density slope. ",
             "The density may not be log-concave on this domain, or 'upper'/'x_init' may be misspecified.")
      }
      x <- c(x, x[k] + step)
      k <- k + 1
      step <- step * 2
    }
  }
  sort(unique(x))
}

## ---- hull construction -----------------------------------------------------

## Builds the tangent-line upper hull and its intersection points z, plus
## bookkeeping needed for evaluation/sampling. x, h, hp must already
## correspond to the same (sorted) set of abscissae.
.build_hull <- function(x, h, hp, lower, upper) {
  o <- order(x)
  x <- x[o]; h <- h[o]; hp <- hp[o]
  k <- length(x)
  z <- numeric(k + 1)
  z[1] <- lower
  z[k + 1] <- upper
  if (k > 1) {
    for (i in 1:(k - 1)) {
      dhp <- hp[i] - hp[i + 1]
      if (abs(dhp) < 1e-12) {
        z[i + 1] <- (x[i] + x[i + 1]) / 2
      } else {
        z[i + 1] <- (h[i + 1] - h[i] - x[i + 1] * hp[i + 1] + x[i] * hp[i]) / dhp
      }
    }
  }
  list(x = x, h = h, hp = hp, z = z, k = k, lower = lower, upper = upper)
}

## Upper hull (envelope): min of the tangent lines, evaluated piecewise via
## the intersection points z.
.eval_upper <- function(hull, xt) {
  i <- findInterval(xt, hull$z, all.inside = TRUE)
  hull$h[i] + hull$hp[i] * (xt - hull$x[i])
}

## Lower hull (squeeze): piecewise-linear chord through the abscissae;
## -Inf outside [x_1, x_k], where no squeeze is available.
.eval_lower <- function(hull, xt) {
  x <- hull$x; h <- hull$h; k <- hull$k
  if (k < 2 || xt < x[1] || xt > x[k]) return(-Inf)
  i <- findInterval(xt, x, all.inside = TRUE)
  h[i] + (h[i + 1] - h[i]) / (x[i + 1] - x[i]) * (xt - x[i])
}

## ---- sampling from the piecewise-exponential upper hull --------------------

## log of the (unnormalized) integral of exp(upper hull) over segment i,
## computed in a numerically stable way (handles infinite segment ends).
.segment_log_weight <- function(hull, i) {
  x_i <- hull$x[i]; h_i <- hull$h[i]; hp_i <- hull$hp[i]
  a <- hull$z[i]; b <- hull$z[i + 1]
  if (abs(hp_i) < 1e-10) {
    return(h_i + log(b - a))
  }
  e_a <- hp_i * (a - x_i)
  e_b <- hp_i * (b - x_i)
  M <- max(e_a, e_b)
  diff <- exp(e_b - M) - exp(e_a - M)
  h_i + M + log(abs(diff)) - log(abs(hp_i))
}

.segment_probs <- function(hull) {
  logw <- vapply(seq_len(hull$k), function(i) .segment_log_weight(hull, i), numeric(1))
  m <- max(logw)
  w <- exp(logw - m)
  w / sum(w)
}

## Inverse-CDF draw of x within segment i (stable via the same M-shift trick).
.sample_segment <- function(hull, i) {
  x_i <- hull$x[i]; hp_i <- hull$hp[i]
  a <- hull$z[i]; b <- hull$z[i + 1]
  u <- runif(1)
  if (abs(hp_i) < 1e-10) {
    return(a + u * (b - a))
  }
  e_a <- hp_i * (a - x_i)
  e_b <- hp_i * (b - x_i)
  M <- max(e_a, e_b)
  A <- exp(e_b - M)
  B <- exp(e_a - M)
  x_i + (1 / hp_i) * (M + log(u * A + (1 - u) * B))
}

.sample_from_hull <- function(hull) {
  probs <- .segment_probs(hull)
  i <- sample.int(hull$k, size = 1, prob = probs)
  .sample_segment(hull, i)
}

## ---- log-concavity checking -------------------------------------------------

## For a log-concave h, the tangent slopes h'(x_i) must be non-increasing in
## x. Checks a newly evaluated point against its sorted neighbours.
.check_concavity_at_insert <- function(x, hp, x_new, hp_new, tol = 1e-4) {
  idx <- findInterval(x_new, x)
  if (idx >= 1 && hp[idx] < hp_new - tol) {
    stop("ars: non-log-concave density detected (log-density slope increased near x = ",
         signif(x_new, 4), "). ARS requires the target's log-density to be concave.")
  }
  if (idx < length(x) && hp[idx + 1] > hp_new + tol) {
    stop("ars: non-log-concave density detected (log-density slope increased near x = ",
         signif(x_new, 4), "). ARS requires the target's log-density to be concave.")
  }
  invisible(TRUE)
}

## Inserts (x_new, h_new, hp_new) into the hull and rebuilds it.
.update_hull <- function(hull, x_new, h_new, hp_new) {
  x <- c(hull$x, x_new); h <- c(hull$h, h_new); hp <- c(hull$hp, hp_new)
  .build_hull(x, h, hp, hull$lower, hull$upper)
}

## ---- main driver -------------------------------------------------------

#' Adaptive rejection sampling from a log-concave density.
#'
#' @param g        Density function, e.g. \code{dnorm}, \code{dexp}; called
#'                 as \code{g(x, ...)}. May be unnormalized (any constant
#'                 multiple works) and does not need to integrate to 1.
#' @param n        Number of samples to draw (positive integer).
#' @param lower    Lower bound of the support (default -Inf).
#' @param upper    Upper bound of the support (default Inf).
#' @param x_init   Optional numeric vector (>= 2 values) of initial
#'                 abscissae strictly inside (lower, upper); useful when
#'                 auto-initialization struggles to locate the density.
#' @param ...      Additional arguments passed through to \code{g}
#'                 (e.g. \code{mean}, \code{sd}, \code{rate}, \code{shape}).
#' @param deriv_eps Step size used for the numerical derivative of log(g).
#' @param tol      Numerical tolerance used in the log-concavity checks.
#' @param max_iter Safety cap on proposal iterations.
#' @param verbose  If TRUE, prints a short diagnostic summary at the end.
#'
#' @return A numeric vector of length \code{n} of samples from (a
#'   distribution proportional to) \code{g}, with attributes \code{n_iter},
#'   \code{n_eval}, and \code{n_hull_points} describing the run.
ars <- function(g, n, lower = -Inf, upper = Inf, x_init = NULL, ...,
                 deriv_eps = 1e-6, tol = 1e-4, max_iter = 200000, verbose = FALSE) {

  .validate_inputs(g, n, lower, upper, x_init)
  n <- as.integer(round(n))

  h  <- .make_h(g, ...)
  hp <- function(x) .h_prime(h, x, eps = deriv_eps)

  x0 <- .initial_abscissae(h, hp, lower, upper, x_init)
  h0  <- vapply(x0, h, numeric(1))
  hp0 <- vapply(x0, hp, numeric(1))

  if (any(!is.finite(h0))) {
    stop("ars: initial abscissae fall where the density is zero; supply 'x_init' inside the support.")
  }
  if (any(diff(hp0) > tol)) {
    stop("ars: non-log-concave density detected among initial abscissae ",
         "(log-density slope is not non-increasing). ARS requires a log-concave target density.")
  }

  hull <- .build_hull(x0, h0, hp0, lower, upper)

  samples <- numeric(n)
  n_accept <- 0L
  n_eval <- 0L
  iter <- 0L

  while (n_accept < n) {
    iter <- iter + 1L
    if (iter > max_iter) {
      stop("ars: exceeded max_iter (", max_iter, ") without collecting ", n,
           " samples; check that the density and domain are correctly specified.")
    }

    xt <- .sample_from_hull(hull)
    w  <- runif(1)
    lk <- .eval_lower(hull, xt)
    uk <- .eval_upper(hull, xt)

    if (log(w) <= lk - uk) {
      n_accept <- n_accept + 1L
      samples[n_accept] <- xt
      next
    }

    n_eval <- n_eval + 1L
    hxt <- h(xt)

    if (hxt > uk + tol) {
      stop("ars: non-log-concave density detected (the log-density exceeds its supporting ",
           "tangent hull at x = ", signif(xt, 4), "). ARS requires the target's log-density ",
           "to be concave over the given domain.")
    }

    if (log(w) <= hxt - uk) {
      n_accept <- n_accept + 1L
      samples[n_accept] <- xt
    }

    if (!any(abs(hull$x - xt) < 1e-10)) {
      hpxt <- hp(xt)
      .check_concavity_at_insert(hull$x, hull$hp, xt, hpxt, tol = tol)
      hull <- .update_hull(hull, xt, hxt, hpxt)
    }
  }

  if (verbose) {
    message(sprintf(
      "ars: collected %d samples in %d proposals (%d full density evaluations, %d final hull points).",
      n, iter, n_eval, hull$k))
  }

  result <- samples
  attr(result, "n_iter") <- iter
  attr(result, "n_eval") <- n_eval
  attr(result, "n_hull_points") <- hull$k
  result
}

## ---- formal test suite ---------------------------------------------------

#' Runs a suite of tests comparing ars() output against known distributions
#' and known-invalid inputs, printing "NAME: PASS"/"NAME: FAIL" plus
#' mean/sd/goodness-of-fit statistics for each.
test <- function(seed = 42, n = 3000, verbose = TRUE) {
  set.seed(seed)
  results <- list()

  cat("=======================================================\n")
  cat("Adaptive Rejection Sampling (Gilks & Wild, 1992) - tests\n")
  cat("=======================================================\n\n")

  ## Case where a valid sample is expected: compare mean/sd + a
  ## Kolmogorov-Smirnov goodness-of-fit test against the known CDF.
  run_case <- function(name, sampler, true_mean, true_sd, cdf_name, cdf_args = list(),
                        save_to = NULL) {
    cat(sprintf("[%s] drawing samples...\n", name))
    ok <- TRUE
    err_msg <- NULL
    samples <- NULL
    tryCatch({
      samples <- sampler()
    }, error = function(e) {
      ok <<- FALSE
      err_msg <<- conditionMessage(e)
    })

    if (!ok) {
      cat(sprintf("%s: FAIL | unexpected error while sampling: %s\n\n", name, err_msg))
      results[[name]] <<- FALSE
      return(invisible(NULL))
    }

    emp_mean <- mean(samples)
    emp_sd <- sd(samples)
    ks <- do.call(ks.test, c(list(x = as.numeric(samples), y = cdf_name), cdf_args))

    mean_ok <- abs(emp_mean - true_mean) < 5 * true_sd / sqrt(length(samples))
    sd_ok <- abs(emp_sd - true_sd) < 0.25 * true_sd
    ks_ok <- ks$p.value > 0.01
    passed <- mean_ok && sd_ok && ks_ok
    status <- if (passed) "PASS" else "FAIL"

    cat(sprintf("  mean = %.4f (true = %.4f)\n", emp_mean, true_mean))
    cat(sprintf("  sd   = %.4f (true = %.4f)\n", emp_sd, true_sd))
    cat(sprintf("  KS test vs. %s: D = %.4f, p-value = %.4f\n", cdf_name, ks$statistic, ks$p.value))
    cat(sprintf("%s: %s\n\n", name, status))
    results[[name]] <<- passed

    if (!is.null(save_to)) {
      writeLines(format(as.numeric(samples), digits = 10), save_to)
      cat(sprintf("  (saved %d samples to %s)\n\n", length(samples), save_to))
    }
    invisible(samples)
  }

  ## Case where an error is expected (invalid input / non-log-concave density).
  run_error_case <- function(name, sampler, expected_pattern) {
    cat(sprintf("[%s] expecting an error...\n", name))
    caught <- FALSE
    msg <- ""
    tryCatch({
      sampler()
    }, error = function(e) {
      caught <<- TRUE
      msg <<- conditionMessage(e)
    })
    passed <- caught && grepl(expected_pattern, msg, ignore.case = TRUE)
    status <- if (passed) "PASS" else "FAIL"
    if (caught) {
      cat(sprintf("  caught: %s\n", msg))
    } else {
      cat("  no error was raised (expected one)\n")
    }
    cat(sprintf("%s: %s\n\n", name, status))
    results[[name]] <<- passed
  }

  ## -- 1. Standard normal, unbounded domain -------------------------------
  run_case("NORMAL_STANDARD",
            function() ars(dnorm, n, lower = -Inf, upper = Inf),
            true_mean = 0, true_sd = 1, cdf_name = "pnorm",
            save_to = "/app/normal_samples.txt")

  ## -- 2. Shifted/scaled normal, exercising '...' pass-through ------------
  run_case("NORMAL_SHIFTED_SCALED",
            function() ars(dnorm, n, lower = -Inf, upper = Inf, mean = 5, sd = 2),
            true_mean = 5, true_sd = 2, cdf_name = "pnorm", cdf_args = list(mean = 5, sd = 2))

  ## -- 3. Exponential(rate = 1), half-bounded domain ----------------------
  run_case("EXPONENTIAL_RATE1",
            function() ars(dexp, n, lower = 0, upper = Inf),
            true_mean = 1, true_sd = 1, cdf_name = "pexp",
            save_to = "/app/exponential_samples.txt")

  ## -- 4. Gamma(shape = 3, rate = 1), log-concave since shape >= 1 --------
  run_case("GAMMA_SHAPE3",
            function() ars(dgamma, n, lower = 0, upper = Inf, shape = 3, rate = 1),
            true_mean = 3, true_sd = sqrt(3), cdf_name = "pgamma", cdf_args = list(shape = 3, rate = 1))

  ## -- 5. Invalid sample count ---------------------------------------------
  run_error_case("INVALID_N_NEGATIVE",
                  function() ars(dnorm, n = -10),
                  expected_pattern = "positive integer")

  ## -- 6. Invalid domain ----------------------------------------------------
  run_error_case("INVALID_DOMAIN",
                  function() ars(dnorm, n = 10, lower = 5, upper = -5),
                  expected_pattern = "lower.*upper|domain")

  ## -- 7. Invalid density function type -------------------------------------
  run_error_case("INVALID_DENSITY_TYPE",
                  function() ars("not a function", n = 10),
                  expected_pattern = "must be a function")

  ## -- 8. Non-log-concave density (Cauchy is convex-tailed) -----------------
  ## x_init deliberately spans the convex tail regions (|x| > 1) so the
  ## log-concavity check fires immediately and deterministically.
  run_error_case("NON_LOG_CONCAVE_CAUCHY",
                  function() ars(dcauchy, n = 100, lower = -Inf, upper = Inf,
                                  x_init = c(-3, -1, 1, 3)),
                  expected_pattern = "non-log-concave")

  cat("=======================================================\n")
  n_pass <- sum(unlist(results))
  n_total <- length(results)
  cat(sprintf("SUMMARY: %d / %d tests passed\n", n_pass, n_total))
  cat("=======================================================\n")

  invisible(results)
}

if (!interactive()) {
  test()
}

