arguments.new_string:
## Finite-difference derivative of h. Uses a central difference away from
## the domain boundaries, and falls back to a one-sided difference when the
## central stencil would probe outside (lower, upper) (e.g. near x = 0 for
## an Exponential density), which would otherwise evaluate h at a point of
## zero density (-Inf) and corrupt the estimated slope.
.h_prime <- function(h, x, eps = 1e-6, lower = -Inf, upper = Inf) {
  x_lo <- x - eps
  x_hi <- x + eps
  if (x_lo <= lower) {
    return((h(x + eps) - h(x)) / eps)
  }
  if (x_hi >= upper) {
    return((h(x) - h(x - eps)) / eps)
  }
  (h(x_hi) - h(x_lo)) / (2 * eps)
}

