arguments.command:
sed '$ d;$ d;$ d' ars.R > /tmp/ars_debug.R && tail -5 /tmp/ars_debug.R
echo "---"
cat >> /tmp/ars_debug.R << 'EOF'
set.seed(42)
h <- .make_h(dexp)
hp <- function(x) .h_prime(h, x, eps=1e-6, lower=0, upper=Inf)
x0 <- .initial_abscissae(h, hp, 0, Inf, NULL)
cat("x0:", x0, "\n")
h0 <- vapply(x0, h, numeric(1)); hp0 <- vapply(x0, hp, numeric(1))
cat("h0:", h0, "hp0:", hp0, "\n")
hull <- .build_hull(x0, h0, hp0, 0, Inf)
str(hull)

for (i in 1:2000) {
  xt <- .sample_from_hull(hull)
  w <- runif(1)
  lk <- .eval_lower(hull, xt)
  uk <- .eval_upper(hull, xt)
  if (log(w) <= lk - uk) next
  hxt <- h(xt)
  if (hxt > uk + 1e-4) { cat("nonconcave at", xt, "\n"); break }
  hpxt <- hp(xt)
  if (!any(abs(hull$x - xt) < 1e-10)) {
    tryCatch({
      .check_concavity_at_insert(hull$x, hull$hp, xt, hpxt, tol=1e-4)
      hull <- .update_hull(hull, xt, hxt, hpxt)
    }, error = function(e) {
      cat("iter", i, "xt=", xt, "hpxt=", hpxt, "ERR:", conditionMessage(e), "\n")
    })
  }
  if (i %% 200 == 0) cat("iter", i, "k=", hull$k, "z_range:", range(hull$z), "\n")
}
EOF
Rscript /tmp/ars_debug.R 2>&1 | tail -60

